/** Public engine types (runtime-design.md §3). Everything in `Data` is plain JSON. */

import type { Stored } from './values.ts';
import type { ChoiceValue, Id, Plan } from './plan.ts';

export type Clock = () => number;
export type Device = 'phone' | 'tablet' | 'desktop';
export type QuestionState = 'not-reached' | 'irrelevant' | 'unanswered' | 'answered';
export type QuotaResult = 'open' | 'full';

export interface StartOptions {
	/** Positive integer, 1 … 2^53 − 1, generated by the server (semantics §7). */
	sessionSeed: number;
	/** Conditions assigned by the server, by assigned-variable id. Missing ones are drawn here. */
	assigned?: Record<Id, ChoiceValue>;
	/** Injected clock (ms). The engine never reads the real time. */
	clock: Clock;
	language?: string;
	device?: Device | null;
	/** URL parameters, for `embedded` variables. Recorded, never trusted for assignment. */
	urlParams?: Record<string, string>;
	sessionId?: string | null;
}

/** A position in the flow: a node list and an index into it. See engine.ts `listFor`. */
export interface Frame {
	k: string;
	i: number;
}

export interface Orders {
	/** Randomiser id → child flow-node ids in realised order (only the picked ones). */
	blocks: Record<Id, Id[]>;
	/** Page id → item ids in realised order (itemOrder: shuffle). */
	items: Record<Id, Id[]>;
	/** Question id → choice codes in realised order (choiceOrder: shuffle). */
	choices: Record<Id, ChoiceValue[]>;
}

export type PageError =
	| { kind: 'required' }
	| { kind: 'constraint' }
	| { kind: 'invalid'; code: string };

export interface QuotaEffect {
	kind: 'quota';
	/** The quotaCheck node; the server call is idempotent per (session, node). */
	nodeId: Id;
	quota: Id;
}
export interface EndEffect {
	kind: 'end';
	outcome: Id;
	nodeId: Id | null;
}
/**
 * Seam for researcher hooks (task R7, runtime-design.md §7a): every hook call will be an
 * engine effect with an invocation id and the state revision it saw. The v1 engine never
 * emits one; `resolve` rejects hook results until R7 defines their actions.
 */
export interface HookEffect {
	kind: 'hook';
	invocationId: string;
	event: string;
	revision: number;
}
export type Effect = QuotaEffect | EndEffect | HookEffect;

export interface HistoryEntry {
	page: Id;
	cursor: Frame[];
	shownAt: number;
}

export interface Pending {
	effect: QuotaEffect;
	cursor: Frame[];
}

export interface StepResult {
	outcome: 'advanced' | 'invalid' | 'effect' | 'ended';
	to?: Id | null;
	errors?: Record<Id, PageError>;
	effect?: Effect;
}

interface EventBase {
	seq: number;
	t: number;
	rev: number;
	/** Set when the call was refused; the event changed nothing else. */
	rejected?: string;
}
export type EngineEvent =
	| (EventBase & {
			type: 'start';
			sessionSeed: number;
			assigned: Record<Id, ChoiceValue>;
			language: string;
			device: Device | null;
			urlParams: Record<string, string>;
			sessionId: string | null;
	  })
	| (EventBase & { type: 'answer'; item: Id; value: Stored; invalid?: string })
	| (EventBase & { type: 'next'; from: Id | null; result?: StepResult })
	| (EventBase & { type: 'back'; from: Id | null; to?: Id | null })
	| (EventBase & {
			type: 'resolve';
			effect: { kind: string; nodeId?: Id; invocationId?: string };
			value: unknown;
			result?: StepResult;
	  })
	| (EventBase & { type: 'language'; language: string });

export interface Data {
	format: 'osp-engine-state/1';
	planChecksum: string;
	sessionSeed: number;
	sessionId: string | null;
	language: string;
	device: Device | null;
	urlParams: Record<string, string>;
	startedAt: number;
	revision: number;
	/** Stored answers (absent = no value). Kept while hidden until a page submit clears them. */
	values: Record<Id, Stored>;
	/** Questions whose last input could not be read (e.g. "12a" for an integer). */
	invalid: Record<Id, string>;
	/** Pages the flow has reached (shown or skipped as empty). */
	reachedPages: Record<Id, true>;
	conditions: Record<Id, ChoiceValue>;
	conditionSource: Record<Id, 'server' | 'seeded'>;
	/** Assigned variables whose `assign` node has been reached (visible to expressions). */
	assignReached: Record<Id, true>;
	orders: Orders;
	/** quotaCheck node id → recorded server result. */
	quotas: Record<Id, QuotaResult>;
	/** Shown pages on the current path; the last one is the current page. */
	history: HistoryEntry[];
	pending: Pending | null;
	errors: Record<Id, PageError>;
	ended: { outcome: Id; nodeId: Id | null; at: number } | null;
	events: EngineEvent[];
}

export interface State {
	readonly plan: Plan;
	readonly clock: Clock;
	readonly data: Data;
}

export interface Snapshot {
	format: 'osp-engine-snapshot/1';
	planChecksum: string;
	revision: number;
	data: Data;
}

/** Text after piping. `value` parts are participant data: HTML-escape them when rendering. */
export type RenderedText = Array<{ kind: 'text'; text: string } | { kind: 'value'; text: string }>;

export interface ViewChoice {
	value: ChoiceValue;
	label: RenderedText;
}

export interface ViewItem {
	id: Id;
	type: string;
	label: RenderedText;
	help: RenderedText | null;
	required: boolean;
	state: QuestionState | null;
	value: Stored;
	error: (PageError & { message: RenderedText | null }) | null;
	choices: ViewChoice[] | null;
}

export interface Position {
	randomiserId: Id;
	index: number;
	of: number;
}

export interface PageView {
	status: 'page' | 'pending' | 'ended';
	page: Id | null;
	block: Id | null;
	language: string;
	title: RenderedText;
	items: ViewItem[];
	errors: Record<Id, PageError & { message: RenderedText | null }>;
	nav: { back: boolean; next: boolean } | null;
	/** Where focus goes (runtime-design.md §6): the heading, or the error summary after a failed next. */
	focus: 'heading' | 'error-summary' | null;
	effect: Effect | null;
	end: { outcome: Id; message: RenderedText | null } | null;
	trial: number;
	position: Position | null;
}

export interface AnswerRecord {
	state: QuestionState;
	value: Stored;
}

export interface ResponseRecord {
	format: 'osp-response/1';
	surveyId: Id;
	surveyVersion: number | null;
	planVersion: string;
	planChecksum: string;
	engineVersion: string;
	sessionSeed: number;
	sessionId: string | null;
	language: string;
	device: Device | null;
	end: Id | null;
	endNode: Id | null;
	allocation: 'server' | 'seeded';
	/** Exactly the conditions the server sent at start (osp_runtime.validate_record checks it). */
	assigned: Record<Id, ChoiceValue>;
	/** All conditions in force, including any the engine drew itself. */
	conditions: Record<Id, ChoiceValue>;
	conditionSources: Record<Id, 'server' | 'seeded'>;
	orders: Orders;
	answers: Record<Id, AnswerRecord>;
	csvState: Record<string, QuestionState>;
	embedded: Record<Id, string | number | null>;
	computed: Record<Id, string | boolean | null>;
	quotas: Record<Id, QuotaResult>;
	urlParams: Record<string, string>;
	startedAt: number;
	endedAt: number | null;
	revision: number;
	events: EngineEvent[];
}

export interface Ctx {
	trial: number;
	trialId: Id | null;
	blockId: Id | null;
	position: Position | null;
	pagesDone: number;
	pagesEstimated: number;
	conditions: Record<Id, ChoiceValue>;
	language: string;
	device: Device | null;
	elapsedMs: number;
	trialElapsedMs: number;
	results: Record<Id, AnswerRecord>;
	vars: Record<Id, string | number | boolean | null>;
	sessionId: string | null;
}

export class EngineError extends Error {
	constructor(
		readonly code: string,
		message: string
	) {
		super(message);
	}
}
